namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, Fresh mozzarella, San Marzano tomatoes, Fresh basil, Olive oil, Salt", Steps = "1. Preheat oven to 475°F\n2. Roll out dough on floured surface\n3. Spread crushed tomatoes evenly\n4. Add torn mozzarella pieces\n5. Bake 10-12 minutes until crust is golden\n6. Top with fresh basil and drizzle olive oil", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper", Steps = "1. Cook spaghetti in salted water\n2. Crisp guanciale in a pan\n3. Whisk eggs with grated pecorino and pepper\n4. Toss hot pasta with guanciale\n5. Remove from heat, stir in egg mixture\n6. Serve immediately with extra pecorino", AverageRating = 4.8, RatingCount = 20 },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Heavy cream, Onion, Garlic, Ginger", Steps = "1. Marinate chicken in yogurt and spices for 2 hours\n2. Grill or broil chicken until charred\n3. Sauté onion, garlic, and ginger\n4. Add tomato sauce and garam masala\n5. Simmer 15 minutes, add cream\n6. Add chicken pieces and simmer 5 more minutes", AverageRating = 4.7, RatingCount = 15 },
        new Recipe { Id = 4, Title = "Vegetable Pad Thai", Category = "Thai", Ingredients = "Rice noodles, Tofu, Bean sprouts, Peanuts, Lime, Tamarind paste, Fish sauce, Sugar, Eggs", Steps = "1. Soak rice noodles in warm water 30 minutes\n2. Press and cube tofu, pan-fry until golden\n3. Make sauce: tamarind, fish sauce, sugar\n4. Stir-fry noodles with sauce\n5. Push aside, scramble eggs in pan\n6. Toss everything together, top with peanuts and lime", AverageRating = 4.3, RatingCount = 8 },
        new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheddar cheese, Sour cream, Taco seasoning", Steps = "1. Brown ground beef in skillet\n2. Add taco seasoning and water, simmer 5 minutes\n3. Warm taco shells in oven\n4. Dice tomato and shred lettuce\n5. Assemble tacos with beef and toppings\n6. Serve with sour cream and salsa", AverageRating = 4.1, RatingCount = 10 },
        new Recipe { Id = 6, Title = "Miso Ramen", Category = "Japanese", Ingredients = "Ramen noodles, Miso paste, Pork belly, Soft-boiled egg, Green onions, Nori, Chicken broth, Garlic", Steps = "1. Simmer chicken broth with garlic 30 minutes\n2. Whisk in miso paste (don't boil)\n3. Slice braised pork belly\n4. Cook ramen noodles per package directions\n5. Assemble: noodles, broth, pork, halved egg\n6. Garnish with green onions and nori", AverageRating = 4.6, RatingCount = 14 },
        new Recipe { Id = 7, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime juice, Red onion, Cilantro, Jalapeño, Tomato, Salt", Steps = "1. Halve and pit ripe avocados\n2. Mash to desired consistency\n3. Dice onion, tomato, jalapeño finely\n4. Fold vegetables into avocado\n5. Add lime juice, chopped cilantro, salt\n6. Serve immediately with tortilla chips", AverageRating = 4.4, RatingCount = 18 },
        new Recipe { Id = 8, Title = "Green Curry", Category = "Thai", Ingredients = "Green curry paste, Coconut milk, Chicken breast, Thai basil, Bamboo shoots, Fish sauce, Sugar, Thai eggplant", Steps = "1. Heat coconut cream in wok until oil separates\n2. Fry curry paste 2 minutes until fragrant\n3. Add sliced chicken, cook through\n4. Pour in remaining coconut milk\n5. Add bamboo shoots, eggplant, season with fish sauce and sugar\n6. Finish with Thai basil leaves", AverageRating = 4.5, RatingCount = 11 },
    };

    private readonly Dictionary<(int recipeId, string visitorId), int> _ratings = new();

    public List<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public List<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipe(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars, string visitorId)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe == null || stars < 1 || stars > 5) return;

        var key = (recipeId, visitorId);
        bool isUpdate = _ratings.ContainsKey(key);
        int oldRating = isUpdate ? _ratings[key] : 0;

        _ratings[key] = stars;

        if (isUpdate)
        {
            double totalStars = recipe.AverageRating * recipe.RatingCount - oldRating + stars;
            recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
        }
        else
        {
            double totalStars = recipe.AverageRating * recipe.RatingCount + stars;
            recipe.RatingCount++;
            recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
        }
    }

    public void SubmitRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _recipes.Max(r => r.Id) + 1,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        };
        _recipes.Add(recipe);
    }
}

