@page "/category/{CategoryName}"
@inject RecipeHub.Services.RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeHub</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h4 class="card-title">@recipe.Title</h4>
                        <p class="card-text text-muted">
                            @if (recipe.RatingCount > 0)
                            {
                                <span>⭐ @recipe.AverageRating / 5 (@recipe.RatingCount ratings)</span>
                            }
                            else
                            {
                                <span>No ratings yet</span>
                            }
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-link">← Back to Categories</a>

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private List<RecipeHub.Models.Recipe> recipes = new();

    protected override void OnInitialized()
    {
        recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@inject RecipeHub.Services.RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeHub</PageTitle>

@if (recipe == null)
{
    <p>Recipe not found.</p>
}
else
{
    <h1>@recipe.Title</h1>
    <p class="text-muted">Category: <a href="/category/@recipe.Category">@recipe.Category</a></p>

    <div class="mb-4">
        <h3>Rating</h3>
        <p>⭐ @recipe.AverageRating / 5 (@recipe.RatingCount ratings)</p>
        <StarRating RecipeId="@recipe.Id" />
    </div>

    <div class="mb-4">
        <h3>Ingredients</h3>
        <ul>
            @foreach (var ingredient in recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
            {
                <li>@ingredient</li>
            }
        </ul>
    </div>

    <div class="mb-4">
        <h3>Steps</h3>
        <ol>
            @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                var text = step.TrimStart();
                if (text.Length > 2 && text[1] == '.')
                    text = text[3..];
                <li>@text</li>
            }
        </ol>
    </div>

    <a href="/category/@recipe.Category" class="btn btn-link">← Back to @recipe.Category Recipes</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeHub.Models.Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeService.GetRecipe(Id);
    }
}

@rendermode InteractiveServer
@inject RecipeHub.Services.RecipeService RecipeService

<div class="star-rating">
    <span>Rate this recipe: </span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= selectedRating ? "selected" : "")"
              @onclick="() => Rate(star)"
              style="cursor: pointer; font-size: 1.5rem;">
            @(star <= selectedRating ? "★" : "☆")
        </span>
    }
    @if (submitted)
    {
        <span class="text-success ms-2">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int selectedRating;
    private bool submitted;
    private string visitorId = Guid.NewGuid().ToString();

    private void Rate(int stars)
    {
        selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars, visitorId);
        submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeHub.Services.RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (isSubmitted)
{
    <div class="alert alert-success">
        <h4>Recipe Submitted!</h4>
        <p>Your recipe "<strong>@submission.Title</strong>" has been added. <a href="/category/@submission.Category">View it here</a>.</p>
    </div>
    <button class="btn btn-primary" @onclick="Reset">Submit Another</button>
}
else
{
    <EditForm Model="submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="submission.Title" placeholder="e.g., Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="submission.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in categories)
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="4" @bind-Value="submission.Ingredients"
                placeholder="List ingredients separated by commas (e.g., Flour, Sugar, Butter, Eggs)" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="submission.Steps"
                placeholder="Describe each step on a new line (e.g., 1. Preheat oven to 350°F)" />
        </div>

        <button type="submit" class="btn btn-success" disabled="@(!IsValid)">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeHub.Models.RecipeSubmission submission = new();
    private List<string> categories = new();
    private bool isSubmitted;

    private bool IsValid => !string.IsNullOrWhiteSpace(submission.Title)
        && !string.IsNullOrWhiteSpace(submission.Category)
        && !string.IsNullOrWhiteSpace(submission.Ingredients)
        && !string.IsNullOrWhiteSpace(submission.Steps);

    protected override void OnInitialized()
    {
        categories = RecipeService.GetCategories();
    }

